"""Automated tests for module: Session Management (generated by RK Testing Studio)."""

import re

import pytest
from playwright.sync_api import expect


@pytest.mark.tc('TC_SESS_005')
def test_tc_sess_005_session_persists_after_browser_reload_on(app):
    """TC_SESS_005: Session persists after browser reload on Settings page

    Scenario: SC_SESS_002
    Expected: After reload, the Settings page still shows the heading  Settings  and  Privacy and account data ; no re-authentication is required.
    Note: Step 1: press on  Settings  (a heading) was moved to the radio with that name.
    """
    with app.step('Open the application on the settings view', action='open_view', element=''):
        app.open_view('settings')
    with app.step('Reload the browser (F5)', action='press', element='settings.settings_radio'):
        app.pages.settings.settings_radio.press('F5'); app.settle()
    with app.step("Verify the heading 'Settings' is shown after reload", action='expect_text', element='settings.settings_heading'):
        expect(app.pages.settings.settings_heading).to_contain_text('Settings')
    with app.step("Verify the heading 'Privacy and account data' is shown after reload", action='expect_text', element='settings.privacy_and_account_data_heading'):
        expect(app.pages.settings.privacy_and_account_data_heading).to_contain_text('Privacy and account data')
